package com.yjiyun.chatflows.runtime.api;
import com.sun.net.httpserver.*; import com.yjiyun.chatflows.runtime.blueprint.*; import com.yjiyun.chatflows.runtime.security.AuthService; import java.io.IOException; import java.util.Map;
public final class DryRunController implements HttpHandler { private final RuntimeService runtime; private final AuthService auth; public DryRunController(RuntimeService r,AuthService a){runtime=r;auth=a;} public void handle(HttpExchange x)throws IOException{try{if(!"POST".equals(x.getRequestMethod())){HttpSupport.json(x,405,Map.of("error","POST required"));return;}auth.require(HttpSupport.bearer(x));Map<String,String> q=HttpSupport.query(x);AgentBlueprint bp=BlueprintJson.read(x.getRequestBody().readAllBytes());if(!req(q,"clientCode").equals(bp.clientCode())||!req(q,"runtimeAgentId").equals(bp.runtimeAgentId()))throw new IllegalArgumentException("query/Blueprint identity mismatch");String response=runtime.dryRun(bp,req(q,"userId"));HttpSupport.json(x,200,Map.of("ok",true,"response",response));}catch(Exception e){HttpSupport.error(x,e);}} private static String req(Map<String,String> q,String k){String v=q.get(k);if(v==null||v.isBlank())throw new IllegalArgumentException(k+" required");return v;} }
